  MT_arrow(110,y1+108,250,y1+108,GRN,4,14)+MT_T(604,y1+56,`${MT_JA} = −c ${MT_D} d${MT_yA}/dz`,{fs:22,fw:800,a:'end'})+MT_T(604,y1+96,'minus sign: high → low',{fs:22,fw:800,a:'end',fill:GRN});
 /* i2: with constant c, the yA profile scales to a cA profile (the worked example: c = 40.6) */
 const y2=y(1);
 const p2=R(1,ORG)+MT_T(40,y2+46,`${MT_yA}: 0.30 → 0.10`,{fs:24,fw:800})+MT_arrow(130,y2+60,130,y2+84,ORG,3,12)+MT_T(150,y2+80,'× c = 40.6',{fs:22,fw:800,fill:ORG})+
  MT_T(40,y2+112,`${MT_cA}: 12.18 → 4.06 mol/m³`,{fs:24,fw:800})+MT_prof(450,y2+30,590,y2+60,ORG)+MT_prof(450,y2+70,590,y2+104,ORG);
 /* i3: the fixed-frame flux is diffusion plus bulk flow */
 const y3=y(2);
 const p3=R(2,GRN)+MT_arrow(40,y3+44,300,y3+44,BLU,6,18)+MT_T(170,y3+32,MT_JA,{fs:22,fw:800,a:'middle',fill:BLU})+MT_arrow(300,y3+44,480,y3+44,GRN,6,18)+MT_T(390,y3+32,'bulk flow',{fs:22,fw:800,a:'middle',fill:GRN})+
  MT_arrow(40,y3+90,480,y3+90,MT_DARK,6,18)+MT_T(500,y3+98,MT_NA,{fs:26,fw:800})+MT_T(260,y3+120,'fixed frame',{fs:20,a:'middle',fill:MT_GREY});
 /* i4: slab balance: in − out = gain */
 const y4=y(3);
 const p4=R(3,PUR)+`<rect x="250" y="${y4+18}" width="110" height="92" rx="6" fill="${PUR}" fill-opacity=".18" stroke="${PUR}" stroke-width="3"/>`+MT_T(305,y4+72,`∂${MT_cA}/∂t`,{fs:24,fw:800,a:'middle',fill:PUR})+
  MT_arrow(100,y4+64,244,y4+64,ORG,5,16)+MT_T(170,y4+52,'in',{fs:22,fw:800,a:'middle',fill:ORG})+MT_arrow(366,y4+64,510,y4+64,ORG,5,16)+MT_T(440,y4+52,'out',{fs:22,fw:800,a:'middle',fill:ORG})+
  MT_T(604,y4+112,'in − out = gain',{fs:22,fw:800,a:'end',fill:PUR});
 /* i5: one initial condition (a clock), two boundary conditions (the two faces) */
 const y5=y(4);
 const p5=R(4,ORG)+`<circle cx="76" cy="${y5+62}" r="36" fill="#FFFFFF" stroke="${ORG}" stroke-width="5"/>`+MT_L(76,y5+62,76,y5+38,MT_DARK,4)+MT_L(76,y5+62,94,y5+70,MT_DARK,4)+MT_T(126,y5+56,'1 initial',{fs:24,fw:800,fill:ORG})+MT_T(126,y5+88,'t = 0',{fs:22,fill:MT_GREY})+
  `<rect x="330" y="${y5+16}" width="200" height="66" fill="${ORG}" fill-opacity=".12"/>`+MT_L(330,y5+12,330,y5+86,MT_DARK,6)+MT_L(530,y5+12,530,y5+86,MT_DARK,6)+MT_T(430,y5+57,'2 boundary',{fs:24,fw:800,a:'middle',fill:ORG})+
  MT_T(330,y5+110,'z = 0',{fs:20,a:'middle',fill:MT_GREY})+MT_T(530,y5+110,'z = L',{fs:20,a:'middle',fill:MT_GREY});
